<script setup>
import { computed,onMounted,onUnmounted,ref } from 'vue';
import { brewApi } from '../api';
import {SALTS,copy,calculateWater} from '../water-chemistry';
const props=defineProps({item:Object});
const emit=defineEmits(['close','changed']);
const snapshot=props.item.water_adjustment;
const stage=ref(copy(snapshot.recipe_stage)),lots=ref({}),note=ref(''),ph=ref(''),confirmed=ref(false),saving=ref(false),error=ref(''),panel=ref(null);
let trigger;
onMounted(()=>{trigger=document.activeElement;panel.value?.focus();});onUnmounted(()=>trigger?.focus());
const calc=computed(()=>{try{return {result:calculateWater(snapshot,stage.value,stage.value.volume_l)};}catch(e){return {error:e.message};}});
const fmt=v=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:3});
const changed=computed(()=>Number(stage.value.volume_l)!==Number(snapshot.recipe_stage.volume_l)||Object.keys(SALTS).some(k=>Number(stage.value.additions[k]?.amount||0)!==Number(snapshot.recipe_stage.additions?.[k]?.amount||0))||Number(stage.value.acid.amount_ml)!==Number(snapshot.recipe_stage.acid?.amount_ml||0));
function trap(event){if(event.key==='Escape'&&!saving.value)emit('close');if(event.key!=='Tab')return;const nodes=[...panel.value.querySelectorAll('button,input,textarea')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
async function submit(){if(saving.value)return;if(!confirmed.value||calc.value.error){error.value=calc.value.error||'请确认已实际完成水质调节';return;}saving.value=true;error.value='';try{const result=await brewApi.taskAction(props.item.task_id,'checkpoint',{version:props.item.version,checkpoint_key:props.item.checkpoint_key,confirmed:true,comment:note.value,water_actual:{volume_l:Number(stage.value.volume_l),additions:Object.fromEntries(Object.keys(SALTS).map(k=>[k,{amount:Number(stage.value.additions[k].amount),lot:lots.value[k]||''}])),acid_ml:Number(stage.value.acid.amount_ml),measured_ph:ph.value}});emit('changed',result);}catch(e){error.value=e.message||'提交失败，输入已保留。';}finally{saving.value=false;}}
</script>
<template><Teleport to="body"><div class="water-task-mask" @click.self="!saving&&$emit('close')"><section ref="panel" class="water-task-drawer" role="dialog" aria-modal="true" aria-labelledby="water-task-title" tabindex="-1" @keydown="trap"><header><div><small>糖化任务 · 水质调节</small><h2 id="water-task-title">{{ item.title }}</h2><p>{{ item.production?.product || item.plan_name }} · {{ item.production?.batch_name || '' }}</p></div><button type="button" :disabled="saving" aria-label="关闭水质调节任务" @click="$emit('close')">×</button></header><form @submit.prevent="submit"><div class="water-task-body"><div class="water-task-source"><strong>{{ snapshot.source.name }}</strong><p>检测日期 {{ snapshot.source.measured_on || '配方手动填写' }} · {{ snapshot.target?.name }}</p><p v-if="snapshot.override_note">修改依据：{{ snapshot.override_note }}</p></div><label class="water-task-volume">实际处理水量 <small>计划 {{ snapshot.recipe_stage.volume_l }} L</small><div><input v-model.number="stage.volume_l" type="number" min="0.001" step="any" required><span>L</span></div></label><p class="water-task-hint">按实际食品级产品投加，水合物、纯度与方案一致。下列用量已带入计划，请现场核对。</p><div v-for="(salt,key) in SALTS" :key="key" class="water-task-salt"><div><strong>{{ salt.name }}</strong><small>{{ salt.formula }} · 纯度 {{ stage.additions[key].purity }}% · 计划 {{ snapshot.recipe_stage.additions?.[key]?.amount||0 }} g</small></div><label><input v-model.number="stage.additions[key].amount" type="number" min="0" step="any" required :aria-label="salt.name+'实际用量'"><span>g</span></label><input v-if="Number(stage.additions[key].amount)>0" v-model.trim="lots[key]" class="water-task-lot" placeholder="原料批次 / 标签（选填）" :aria-label="salt.name+'批次'"></div><div class="water-task-salt"><div><strong>乳酸</strong><small>{{ stage.acid.concentration }}% · {{ stage.acid.density }} g/mL · 计划 {{ snapshot.recipe_stage.acid?.amount_ml||0 }} mL</small></div><label><input v-model.number="stage.acid.amount_ml" type="number" min="0" step="any" required aria-label="实际乳酸用量"><span>mL</span></label></div><label class="water-task-volume">调节后水实测 pH{{ Number(stage.acid.amount_ml)>0?'（加酸后必填）':'（选填）' }}<input v-model="ph" :required="Number(stage.acid.amount_ml)>0" type="number" min="0" max="14" step="0.01" placeholder="现场检测，不是糖化醪 pH"></label><div v-if="calc.result" class="water-task-result"><small>按本次实际投加量计算</small><p>钙 {{ fmt(calc.result.ions.ca) }} · 镁 {{ fmt(calc.result.ions.mg) }} · 钠 {{ fmt(calc.result.ions.na) }} mg/L</p><p>氯离子 {{ fmt(calc.result.ions.cl) }} · 硫酸根 {{ fmt(calc.result.ions.so4) }} mg/L</p><p v-for="warning in calc.result.warnings" :key="warning">{{ warning }}</p></div><label class="water-task-volume">操作说明{{ changed?' / 差异原因（必填）':'（选填）' }}<textarea v-model.trim="note" :required="changed" rows="3" placeholder="记录实际情况；偏离计划时填写原因"></textarea></label><label class="water-task-confirm"><input v-model="confirmed" type="checkbox" required>已核对水源和物料，完成本次水质调节</label><p v-if="error||calc.error" role="alert" class="master-error">{{ error||calc.error }}</p></div><footer><button class="btn btn-primary" type="submit" :disabled="saving||!!calc.error">{{ saving?'提交中…':'确认实际投加并完成' }}</button></footer></form></section></div></Teleport></template>
<style scoped>
.water-task-mask{position:fixed;inset:0;z-index:2400;background:#000a;display:flex;justify-content:flex-end}.water-task-drawer{display:flex;flex-direction:column;width:min(600px,100vw);height:100%;background:#25251f;color:var(--text-primary);outline:none}.water-task-drawer>header{display:flex;justify-content:space-between;gap:16px;padding:24px;border-bottom:1px solid var(--border-default)}header small{color:#d4b36b;font-size:11px}header h2{font-size:23px;margin:10px 0}header p{font-size:12px;color:var(--text-muted);line-height:1.8}header>button{background:none;border:0;color:var(--text-muted);font-size:26px;align-self:flex-start;cursor:pointer}form{display:flex;flex-direction:column;flex:1;min-height:0}.water-task-body{padding:22px 24px;overflow:auto;flex:1}.water-task-source{padding:15px;border:1px solid #d4a85335;background:#d4a85309;border-radius:8px}.water-task-source strong{font-size:14px}.water-task-source p,.water-task-hint{font-size:11px;line-height:1.9;color:var(--text-muted)}.water-task-volume{display:grid;gap:9px;margin:20px 0;font-size:12px}.water-task-volume small{color:var(--text-muted)}.water-task-volume>div,.water-task-salt label{display:flex;align-items:center;gap:10px}.water-task-volume input,.water-task-volume textarea,.water-task-salt input{box-sizing:border-box;min-width:0;width:100%;padding:11px;border:1px solid var(--border-default);border-radius:7px;background:var(--bg-input);color:var(--text-primary);font:inherit}.water-task-volume span,.water-task-salt span{color:var(--text-muted);font-size:12px}.water-task-salt{display:grid;grid-template-columns:minmax(0,1fr) 115px;gap:9px 16px;padding:16px 0;border-bottom:1px solid var(--border-default)}.water-task-salt strong{font-size:13px;font-weight:500}.water-task-salt small{display:block;margin-top:7px;color:var(--text-muted);font-size:10px;line-height:1.8}.water-task-lot{grid-column:1/-1;font-size:11px!important;min-height:34px}.water-task-result{padding:16px;border:1px solid #91bc9140;border-radius:8px;margin:20px 0;background:#91bc9108}.water-task-result small{font-size:11px;color:#b2d3a5}.water-task-result p{font-size:12px;color:var(--text-secondary);line-height:1.9;margin:7px 0}.water-task-confirm{display:flex;align-items:center;gap:9px;font-size:12px;line-height:1.8;margin:20px 0}footer{padding:18px 24px;border-top:1px solid var(--border-default)}footer button{width:100%;min-height:44px}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid #e0bc70;outline-offset:3px}
</style>
